/* Compact ivory/graphite console from the user's latest design. */
(()=>{const main=document.querySelector('main'),instrument=document.querySelector('.instrument'),editor=document.querySelector('#bassEditor'),routing=document.querySelector('#advanced');const workspace=document.createElement('div');workspace.className='console-workspace';instrument.before(workspace);workspace.append(instrument,editor,routing);const output=document.querySelector('.output'),rack=document.querySelector('.macros');const pair=document.createElement('div');pair.className='console-macro-pair';rack.before(pair);pair.append(rack,output);document.body.classList.add('compact-reference');})();
